import assert from "node:assert/strict";
import test from "node:test";
import { buildSquadScopedPrompt } from "./io-scheduler.js";

test("buildSquadScopedPrompt includes squad context", () => {
  const prompt = buildSquadScopedPrompt({
    squad_id: "squad-123",
    prompt: "Share priorities for today",
  });

  assert.equal(
    prompt,
    "[Squad Schedule] Run for squad squad-123. Prompt: Share priorities for today"
  );
});

import { listSchedules, updateScheduleLastRun, type Schedule } from "../store/schedules.js";
import { sendToOrchestrator } from "./orchestrator.js";

let ioSchedulerInterval: ReturnType<typeof setInterval> | undefined;

export function startIoScheduler(): void {
  ioSchedulerInterval = setInterval(() => {
    checkIoSchedules();
  }, 60_000);
  ioSchedulerInterval.unref();
}

function checkIoSchedules(): void {
  const schedules = listSchedules("io");
  const now = new Date();

  for (const schedule of schedules) {
    if (!schedule.enabled) continue;
    if (!isDue(schedule.cron, schedule.last_run, now)) continue;
    if (!schedule.squad_id) {
      console.warn(`[io-scheduler] Schedule ${schedule.id} skipped: missing squad_id.`);
      continue;
    }

    updateScheduleLastRun(schedule.id);

    sendToOrchestrator(buildSquadScopedPrompt(schedule), "io-scheduler", (_text, done) => {
      if (done) {
        console.log(`[io-scheduler] Schedule ${schedule.id} completed.`);
      }
    });
  }
}

export function buildSquadScopedPrompt(schedule: Pick<Schedule, "squad_id" | "prompt">): string {
  const squadId = schedule.squad_id ?? "unknown";
  return `[Squad Schedule] Run for squad ${squadId}. Prompt: ${schedule.prompt}`;
}

function isDue(cron: string, lastRun: string | null, now: Date): boolean {
  const parts = cron.split(" ");
  if (parts.length !== 5) return false;

  const [minSpec, hourSpec, daySpec, monthSpec, weekdaySpec] = parts;

  if (!matchesCronField(minSpec, now.getMinutes())) return false;
  if (!matchesCronField(hourSpec, now.getHours())) return false;
  if (!matchesCronField(daySpec, now.getDate())) return false;
  if (!matchesCronField(monthSpec, now.getMonth() + 1)) return false;
  if (!matchesCronField(weekdaySpec, now.getDay())) return false;

  if (lastRun) {
    const lastDate = new Date(lastRun);
    const diffMs = now.getTime() - lastDate.getTime();
    if (diffMs < 60_000) return false;
  }

  return true;
}

function matchesCronField(spec: string, value: number): boolean {
  if (spec === "*") return true;
  if (spec.includes("-")) {
    const [start, end] = spec.split("-").map(Number);
    return value >= start && value <= end;
  }
  if (spec.includes(",")) {
    return spec.split(",").map(Number).includes(value);
  }
  if (spec.startsWith("*/")) {
    const step = parseInt(spec.slice(2), 10);
    return value % step === 0;
  }
  return parseInt(spec, 10) === value;
}

export function stopIoScheduler(): void {
  if (ioSchedulerInterval) {
    clearInterval(ioSchedulerInterval);
    ioSchedulerInterval = undefined;
  }
}

import { randomUUID } from "node:crypto";
import { getDb } from "./db.js";

export interface Schedule {
  id: string;
  type: "squad" | "io";
  squad_id: string | null;
  cron: string;
  agenda: string;
  prompt: string;
  enabled: number;
  last_run: string | null;
  created_at: string;
}

export function createSchedule(input: {
  type: "squad" | "io";
  cron: string;
  squad_id: string;
  agenda?: string;
  prompt?: string;
}): Schedule {
  const squadId = input.squad_id.trim();
  if (!squadId) {
    throw new Error("squad_id is required");
  }

  const db = getDb();
  const id = randomUUID();
  db.prepare(
    `INSERT INTO schedules (id, type, squad_id, cron, agenda, prompt)
     VALUES (?, ?, ?, ?, ?, ?)`
  ).run(
    id,
    input.type,
    squadId,
    input.cron,
    input.agenda ?? "",
    input.prompt ?? ""
  );
  return db.prepare("SELECT * FROM schedules WHERE id = ?").get(id) as Schedule;
}

export function getSchedule(id: string): Schedule | undefined {
  const db = getDb();
  return db.prepare("SELECT * FROM schedules WHERE id = ?").get(id) as Schedule | undefined;
}

export function listSchedules(type?: "squad" | "io"): Schedule[] {
  const db = getDb();
  if (type) {
    return db
      .prepare("SELECT * FROM schedules WHERE type = ? ORDER BY created_at")
      .all(type) as Schedule[];
  }
  return db.prepare("SELECT * FROM schedules ORDER BY created_at").all() as Schedule[];
}

export function updateScheduleLastRun(id: string): void {
  const db = getDb();
  db.prepare("UPDATE schedules SET last_run = datetime('now') WHERE id = ?").run(id);
}

export function toggleSchedule(id: string, enabled: boolean): void {
  const db = getDb();
  db.prepare("UPDATE schedules SET enabled = ? WHERE id = ?").run(enabled ? 1 : 0, id);
}

export function updateSchedule(
  id: string,
  input: { cron?: string; agenda?: string; prompt?: string; enabled?: boolean }
): Schedule {
  const db = getDb();
  const fields: string[] = [];
  const params: any[] = [];

  if (input.cron !== undefined) { fields.push("cron = ?"); params.push(input.cron); }
  if (input.agenda !== undefined) { fields.push("agenda = ?"); params.push(input.agenda); }
  if (input.prompt !== undefined) { fields.push("prompt = ?"); params.push(input.prompt); }
  if (input.enabled !== undefined) { fields.push("enabled = ?"); params.push(input.enabled ? 1 : 0); }

  if (fields.length > 0) {
    params.push(id);
    db.prepare(`UPDATE schedules SET ${fields.join(", ")} WHERE id = ?`).run(...params);
  }
  return db.prepare("SELECT * FROM schedules WHERE id = ?").get(id) as Schedule;
}

export function deleteSchedule(id: string): void {
  const db = getDb();
  db.prepare("DELETE FROM schedules WHERE id = ?").run(id);
}

import { existsSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import Database from "better-sqlite3";
import { PATHS } from "../paths.js";
import { pickSquadColor } from "./squad-colors.js";

let db: Database.Database | undefined;

export function getDb(): Database.Database {
	if (db) return db;

	const dir = dirname(PATHS.db);
	if (!existsSync(dir)) mkdirSync(dir, { recursive: true });

	db = new Database(PATHS.db);
	db.pragma("journal_mode = WAL");
	db.pragma("foreign_keys = ON");

	runMigrations(db);
	return db;
}

function runMigrations(db: Database.Database): void {
	db.exec(`
    CREATE TABLE IF NOT EXISTS meta (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL
    );
  `);

	const version = getSchemaVersion(db);

	if (version < 1) {
		db.exec(`
      CREATE TABLE IF NOT EXISTS squads (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        universe TEXT NOT NULL,
        repo_url TEXT,
        rules TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE TABLE IF NOT EXISTS agents (
        id TEXT PRIMARY KEY,
        squad_id TEXT NOT NULL REFERENCES squads(id) ON DELETE CASCADE,
        character_name TEXT NOT NULL,
        role_title TEXT NOT NULL,
        persona TEXT DEFAULT '',
        is_lead INTEGER NOT NULL DEFAULT 0,
        is_qa INTEGER NOT NULL DEFAULT 0,
        is_test INTEGER NOT NULL DEFAULT 0,
        status TEXT NOT NULL DEFAULT 'idle',
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE TABLE IF NOT EXISTS tasks (
        id TEXT PRIMARY KEY,
        squad_id TEXT NOT NULL REFERENCES squads(id) ON DELETE CASCADE,
        instance_id TEXT,
        agent_id TEXT REFERENCES agents(id) ON DELETE SET NULL,
        description TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending',
        result TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE TABLE IF NOT EXISTS instances (
        id TEXT PRIMARY KEY,
        squad_id TEXT NOT NULL REFERENCES squads(id) ON DELETE CASCADE,
        branch TEXT NOT NULL,
        worktree_path TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'active',
        last_activity TEXT NOT NULL DEFAULT (datetime('now')),
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE TABLE IF NOT EXISTS feed_items (
        id TEXT PRIMARY KEY,
        source TEXT NOT NULL,
        title TEXT NOT NULL,
        content TEXT NOT NULL DEFAULT '',
        read INTEGER NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE TABLE IF NOT EXISTS schedules (
        id TEXT PRIMARY KEY,
        type TEXT NOT NULL CHECK(type IN ('squad', 'io')),
        squad_id TEXT REFERENCES squads(id) ON DELETE CASCADE,
        cron TEXT NOT NULL,
        agenda TEXT NOT NULL DEFAULT '',
        prompt TEXT NOT NULL DEFAULT '',
        enabled INTEGER NOT NULL DEFAULT 1,
        last_run TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE TABLE IF NOT EXISTS session_state (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS mcp_servers (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        type TEXT NOT NULL CHECK(type IN ('stdio', 'http')),
        config TEXT NOT NULL DEFAULT '{}',
        enabled INTEGER NOT NULL DEFAULT 1,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE TABLE IF NOT EXISTS mcp_tools (
        id TEXT PRIMARY KEY,
        server_id TEXT NOT NULL REFERENCES mcp_servers(id) ON DELETE CASCADE,
        name TEXT NOT NULL,
        description TEXT DEFAULT '',
        enabled INTEGER NOT NULL DEFAULT 1
      );
    `);
		setSchemaVersion(db, 1);
	}

	if (version < 2) {
		db.exec(`
      ALTER TABLE squads ADD COLUMN slug TEXT;
    `);
		// Backfill slugs for existing squads
		const squads = db
			.prepare("SELECT id, name FROM squads WHERE slug IS NULL")
			.all() as { id: string; name: string }[];
		const update = db.prepare("UPDATE squads SET slug = ? WHERE id = ?");
		for (const s of squads) {
			const slug = s.name
				.toLowerCase()
				.replace(/[^a-z0-9]+/g, "-")
				.replace(/^-|-$/g, "");
			update.run(slug || s.id, s.id);
		}
		setSchemaVersion(db, 2);
	}

	if (version < 3) {
		db.exec(`
      CREATE TABLE IF NOT EXISTS agent_events (
        id TEXT PRIMARY KEY,
        task_id TEXT NOT NULL,
        type TEXT NOT NULL,
        summary TEXT NOT NULL DEFAULT '',
        payload TEXT NOT NULL DEFAULT '{}',
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE INDEX IF NOT EXISTS idx_agent_events_task_id ON agent_events (task_id);
    `);
		setSchemaVersion(db, 3);
	}

	if (version < 4) {
		db.exec(`
      ALTER TABLE squads ADD COLUMN color TEXT;
    `);
		const squads = db
			.prepare("SELECT id FROM squads WHERE color IS NULL ORDER BY created_at")
			.all() as { id: string }[];
		const update = db.prepare("UPDATE squads SET color = ? WHERE id = ?");
		const usedColors: string[] = [];
		for (let i = 0; i < squads.length; i++) {
			const color = pickSquadColor(usedColors);
			usedColors.push(color);
			update.run(color, squads[i].id);
		}
		setSchemaVersion(db, 4);
	}

	if (version < 5) {
		db.exec(`
      CREATE TABLE IF NOT EXISTS conversation_messages (
        id TEXT PRIMARY KEY,
        conversation_id TEXT NOT NULL,
        role TEXT NOT NULL CHECK(role IN ('user', 'assistant')),
        content TEXT NOT NULL,
        source TEXT NOT NULL DEFAULT 'web',
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE INDEX IF NOT EXISTS idx_conv_messages_conversation_id
        ON conversation_messages(conversation_id);

      CREATE INDEX IF NOT EXISTS idx_conv_messages_created_at
        ON conversation_messages(created_at);

      CREATE VIRTUAL TABLE IF NOT EXISTS conversation_messages_fts
        USING fts5(content, content=conversation_messages, content_rowid=rowid);

      CREATE TRIGGER IF NOT EXISTS conv_messages_fts_insert
        AFTER INSERT ON conversation_messages BEGIN
          INSERT INTO conversation_messages_fts(rowid, content) VALUES (new.rowid, new.content);
        END;

      CREATE TRIGGER IF NOT EXISTS conv_messages_fts_update
        AFTER UPDATE ON conversation_messages BEGIN
          INSERT INTO conversation_messages_fts(conversation_messages_fts, rowid, content) VALUES ('delete', old.rowid, old.content);
          INSERT INTO conversation_messages_fts(rowid, content) VALUES (new.rowid, new.content);
        END;

      CREATE TRIGGER IF NOT EXISTS conv_messages_fts_delete
        AFTER DELETE ON conversation_messages BEGIN
          INSERT INTO conversation_messages_fts(conversation_messages_fts, rowid, content) VALUES ('delete', old.rowid, old.content);
        END;
    `);
		setSchemaVersion(db, 5);
	}

	if (version < 6) {
		db.exec(`
      CREATE TABLE IF NOT EXISTS audit_log (
        id TEXT PRIMARY KEY,
        squad_id TEXT REFERENCES squads(id) ON DELETE SET NULL,
        agent_id TEXT REFERENCES agents(id) ON DELETE SET NULL,
        task_id TEXT,
        action_type TEXT NOT NULL,
        summary TEXT NOT NULL DEFAULT '',
        payload TEXT NOT NULL DEFAULT '{}',
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE INDEX IF NOT EXISTS idx_audit_log_squad_id ON audit_log (squad_id);
      CREATE INDEX IF NOT EXISTS idx_audit_log_agent_id ON audit_log (agent_id);
      CREATE INDEX IF NOT EXISTS idx_audit_log_action_type ON audit_log (action_type);
      CREATE INDEX IF NOT EXISTS idx_audit_log_created_at ON audit_log (created_at);
    `);
		setSchemaVersion(db, 6);
	}

	if (version < 7) {
		db.exec(`
      CREATE TABLE IF NOT EXISTS token_usage (
        id TEXT PRIMARY KEY,
        squad_id TEXT REFERENCES squads(id) ON DELETE CASCADE,
        agent_id TEXT REFERENCES agents(id) ON DELETE SET NULL,
        task_id TEXT REFERENCES tasks(id) ON DELETE SET NULL,
        model TEXT NOT NULL,
        input_tokens INTEGER NOT NULL DEFAULT 0,
        output_tokens INTEGER NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE INDEX IF NOT EXISTS idx_token_usage_squad ON token_usage(squad_id);
      CREATE INDEX IF NOT EXISTS idx_token_usage_agent ON token_usage(agent_id);
      CREATE INDEX IF NOT EXISTS idx_token_usage_task ON token_usage(task_id);
      CREATE INDEX IF NOT EXISTS idx_token_usage_created ON token_usage(created_at);
    `);
		setSchemaVersion(db, 7);
	}

	if (version < 8) {
		db.exec(`
      ALTER TABLE conversation_messages
        ADD COLUMN attachments TEXT NOT NULL DEFAULT '[]';
    `);
		setSchemaVersion(db, 8);
	}

	if (version < 9) {
		db.exec(`
      ALTER TABLE tasks ADD COLUMN title TEXT;
    `);
		setSchemaVersion(db, 9);
	}
}

function getSchemaVersion(db: Database.Database): number {
	const row = db
		.prepare("SELECT value FROM meta WHERE key = 'schema_version'")
		.get() as { value: string } | undefined;
	return row ? parseInt(row.value, 10) : 0;
}

function setSchemaVersion(db: Database.Database, version: number): void {
	db.prepare(
		"INSERT OR REPLACE INTO meta (key, value) VALUES ('schema_version', ?)",
	).run(String(version));
}

export function closeDb(): void {
	if (db) {
		db.close();
		db = undefined;
	}
}

import { homedir } from "node:os";
import { join } from "node:path";

const IO_HOME = join(homedir(), ".io");

export const PATHS = {
  home: IO_HOME,
  config: join(IO_HOME, "config.json"),
  db: join(IO_HOME, "io.db"),
  wiki: join(IO_HOME, "wiki"),
  wikiPages: join(IO_HOME, "wiki", "pages"),
  wikiSquadTemplates: join(IO_HOME, "wiki", "templates", "squad"),
  skills: join(IO_HOME, "skills"),
  mcpConfig: join(IO_HOME, "mcp.json"),
  sessions: join(IO_HOME, "sessions"),
  source: join(IO_HOME, "source"),
  attachments: join(IO_HOME, "attachments"),
} as const;

// Palette complementary to the site's brand gradient (magenta #E43A9C → violet #F041FF)
// Avoiding direct brand colors; using analogous/complementary hues that look cohesive
export const SQUAD_COLOR_PALETTE = [
  "#06b6d4", // cyan (complementary to magenta)
  "#14b8a6", // teal
  "#f59e0b", // amber (warm contrast)
  "#8b5cf6", // violet (analogous)
  "#3b82f6", // blue
  "#10b981", // emerald
  "#f43f5e", // rose (analogous warm)
  "#6366f1", // indigo
] as const;

const DEFAULT_SQUAD_COLOR = "#3b82f6";

export function pickSquadColor(
  usedColors: string[],
  random: () => number = Math.random
): string {
  const used = new Set(usedColors.filter(Boolean).map((c) => c.toLowerCase()));
  const available = SQUAD_COLOR_PALETTE.filter((c) => !used.has(c.toLowerCase()));
  const source = available.length > 0 ? available : SQUAD_COLOR_PALETTE;
  if (source.length === 0) return DEFAULT_SQUAD_COLOR;
  const index = Math.floor(random() * source.length);
  return source[index] ?? DEFAULT_SQUAD_COLOR;
}

import type { CopilotClient, CopilotSession } from "@github/copilot-sdk";
import { approveAll } from "@github/copilot-sdk";
import { getDb } from "../store/db.js";
import { loadConfig } from "../config.js";
import { buildSystemMessage } from "./system-message.js";
import { createTools } from "./tools.js";
import { loadSkillDirectories } from "./skills.js";
import { getMcpServersForSession } from "../mcp/registry.js";
import { resetClient } from "./client.js";
import { addAuditEntry } from "../store/audit-log.js";
import {
  buildAttachmentSummary,
  buildAttachmentPathSummary,
  saveAttachmentsToDisk,
  type MessageAttachment,
  toCopilotBlobAttachments,
} from "../chat/attachments.js";
import { attachTokenTracker } from "./token-tracker.js";

let orchestratorSession: CopilotSession | undefined;
let sessionCreatePromise: Promise<CopilotSession> | undefined;
let healthCheckInterval: ReturnType<typeof setInterval> | undefined;
let activeMessageAttachments: MessageAttachment[] = [];

interface OrchestratorOptions {
  selfEdit: boolean;
}

type MessageCallback = (text: string, done: boolean) => void;

interface QueuedMessage {
  prompt: string;
  source: string;
  callback: MessageCallback;
  attachments: MessageAttachment[];
}

const messageQueue: QueuedMessage[] = [];
let processing = false;

export async function initOrchestrator(
  client: CopilotClient,
  opts: OrchestratorOptions
): Promise<void> {
  await ensureOrchestratorSession(client, opts);
  startHealthCheck(client, opts);
}

async function ensureOrchestratorSession(
  client: CopilotClient,
  opts: OrchestratorOptions
): Promise<CopilotSession> {
  if (orchestratorSession) return orchestratorSession;
  if (sessionCreatePromise) return sessionCreatePromise;

  sessionCreatePromise = createOrResumeSession(client, opts);
  try {
    orchestratorSession = await sessionCreatePromise;
    return orchestratorSession;
  } finally {
    sessionCreatePromise = undefined;
  }
}

async function createOrResumeSession(
  client: CopilotClient,
  opts: OrchestratorOptions
): Promise<CopilotSession> {
  const config = loadConfig();
  const db = getDb();
  const tools = createTools();
  const skillDirs = await loadSkillDirectories();
  const systemMessage = buildSystemMessage(opts.selfEdit);

  const savedId = db
    .prepare("SELECT value FROM session_state WHERE key = 'orchestrator_session_id'")
    .get() as { value: string } | undefined;

  const sessionConfig = {
    model: config.defaultModel,
    streaming: true,
    workingDirectory: process.cwd(),
    systemMessage: { mode: "replace" as const, content: systemMessage },
    tools,
    skillDirectories: skillDirs,
    mcpServers: getMcpServersForSession(),
    onPermissionRequest: approveAll,
    infiniteSessions: {
      enabled: true,
      backgroundCompactionThreshold: 0.8,
      bufferExhaustionThreshold: 0.95,
    },
  };

  let session: CopilotSession;
  if (savedId?.value) {
    try {
      session = await client.resumeSession(savedId.value, sessionConfig);
    } catch {
      session = await client.createSession(sessionConfig);
    }
  } else {
    session = await client.createSession(sessionConfig);
  }

  // Persist session ID
  db.prepare(
    "INSERT OR REPLACE INTO session_state (key, value) VALUES ('orchestrator_session_id', ?)"
  ).run(session.sessionId);

  return session;
}

function startHealthCheck(client: CopilotClient, opts: OrchestratorOptions): void {
  healthCheckInterval = setInterval(async () => {
    try {
      await client.ping();
    } catch {
      console.warn("[io] Health check failed, resetting client...");
      orchestratorSession = undefined;
      const newClient = await resetClient();
      await ensureOrchestratorSession(newClient, opts);
    }
  }, 30_000);
  healthCheckInterval.unref();
}

export async function sendToOrchestrator(
  prompt: string,
  source: string,
  callback: MessageCallback,
  attachments: MessageAttachment[] = []
): Promise<void> {
  addAuditEntry(
    "message_received",
    `Message from ${source}: ${prompt.slice(0, 200)}`,
    {
      source,
      prompt: prompt.slice(0, 1000),
      attachments: attachments.map((attachment) => ({
        name: attachment.name,
        mimeType: attachment.mimeType,
        size: attachment.size,
      })),
    }
  );
  messageQueue.push({ prompt, source, callback, attachments });
  if (!processing) processQueue();
}

async function processQueue(): Promise<void> {
  if (processing) return;
  processing = true;

  while (messageQueue.length > 0) {
    const msg = messageQueue.shift()!;
    try {
      await executeOnSession(msg);
    } catch (err) {
      const errMsg = err instanceof Error ? err.message : "Unknown error";
      msg.callback(`Error: ${errMsg}`, true);
    }
  }

  processing = false;
}

async function executeOnSession(msg: QueuedMessage): Promise<void> {
  if (!orchestratorSession) {
    msg.callback("Error: Orchestrator session not initialized.", true);
    return;
  }

  activeMessageAttachments = msg.attachments;

  const flushTokens = attachTokenTracker(orchestratorSession, {
    agentId: "orchestrator",
  });

  try {
    // Save attachments to disk so orchestrator/squads can access them via filesystem tools
    const savedAttachments = saveAttachmentsToDisk(msg.attachments);
    const pathSummary = buildAttachmentPathSummary(savedAttachments);

    const taggedPrompt = `[via ${msg.source}] ${msg.prompt}${pathSummary || buildAttachmentSummary(msg.attachments)}`;
    let accumulated = "";

    const unsubscribe = orchestratorSession.on("assistant.message_delta", (event: any) => {
      const delta = event.data?.deltaContent ?? "";
      accumulated += delta;
      msg.callback(accumulated, false);
    });

    try {
      const response = await orchestratorSession.sendAndWait(
        {
          prompt: taggedPrompt,
          attachments: toCopilotBlobAttachments(msg.attachments),
        },
        7_200_000 // 2 hours — watchdog handles stale detection
      );
      const finalContent = response?.data?.content ?? accumulated;
      msg.callback(finalContent, true);
    } finally {
      activeMessageAttachments = [];
      unsubscribe();
    }
  } finally {
    flushTokens();
  }
}

export function feedAgentResult(
  taskId: string,
  agentName: string,
  result: string,
  callback: MessageCallback
): void {
  const prompt = `[Agent task completed] @${agentName} finished task ${taskId}:\n\n${result}`;
  sendToOrchestrator(prompt, "background", callback);
}

export function getOrchestratorSession(): CopilotSession | undefined {
  return orchestratorSession;
}

export function getActiveMessageAttachments(): MessageAttachment[] {
  return activeMessageAttachments;
}

import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { z } from "zod";
import { PATHS } from "./paths.js";

const ConfigSchema = z.object({
  telegramBotToken: z.string().optional(),
  authorizedUserId: z.number().optional(),
  telegramEnabled: z.boolean().default(false),
  selfEditEnabled: z.boolean().default(false),
  defaultModel: z.string().default("gpt-4.1"),
  port: z.number().default(3170),
  supabaseUrl: z.string().optional(),
  supabaseAnonKey: z.string().optional(),
  authorizedEmail: z.string().optional(),
  githubToken: z.string().optional(),
  backgroundNotifyMode: z
    .enum(["all", "meaningful", "off"])
    .default("meaningful"),
  backgroundNotifyTelegram: z.boolean().default(true),
  watchdogEnabled: z.boolean().default(true),
  tokenAlertThreshold: z.number().optional(),
});

export type Config = z.infer<typeof ConfigSchema>;

let cachedConfig: Config | undefined;
let configWarning: string | undefined;

/** Returns a warning message if config fell back to defaults on last load. */
export function getConfigWarning(): string | undefined {
  return configWarning;
}

export function loadConfig(): Config {
  if (cachedConfig) return cachedConfig;

  if (!existsSync(PATHS.config)) {
    configWarning = `Config file not found at ${PATHS.config} — using defaults. Run "io setup" or create the file manually.`;
    console.warn(`[io] ⚠️  ${configWarning}`);
    const defaults = ConfigSchema.parse({});
    cachedConfig = defaults;
    return defaults;
  }

  let raw: Record<string, unknown>;
  try {
    raw = JSON.parse(readFileSync(PATHS.config, "utf-8"));
  } catch (err) {
    configWarning = `Config file at ${PATHS.config} is corrupted or unreadable — using defaults. Please restore your config.`;
    console.warn(`[io] ⚠️  ${configWarning}`);
    const defaults = ConfigSchema.parse({});
    cachedConfig = defaults;
    return defaults;
  }

  // Migrate old apiPort field
  if ("apiPort" in raw && !("port" in raw)) {
    raw.port = raw.apiPort;
    delete raw.apiPort;
    saveConfig(raw as any);
  }

  configWarning = undefined;
  cachedConfig = ConfigSchema.parse(raw);
  return cachedConfig;
}

export function saveConfig(config: Partial<Config>): void {
  const dir = dirname(PATHS.config);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });

  let current: Record<string, unknown> = {};
  if (existsSync(PATHS.config)) {
    try {
      current = JSON.parse(readFileSync(PATHS.config, "utf-8"));
    } catch {
      // If file is corrupted, use cached config as baseline to avoid data loss
      if (cachedConfig) {
        current = JSON.parse(JSON.stringify(cachedConfig));
      }
    }
  } else if (cachedConfig) {
    // File doesn't exist but we have a cached config (from earlier load) — use it as baseline
    current = JSON.parse(JSON.stringify(cachedConfig));
  }

  const merged = { ...current, ...config };
  writeFileSync(PATHS.config, JSON.stringify(merged, null, 2) + "\n");
  cachedConfig = ConfigSchema.parse(merged);
}

export function resetConfigCache(): void {
  cachedConfig = undefined;
}

import type { Tool } from "@github/copilot-sdk";
import { defineTool } from "@github/copilot-sdk";
