			},
		}),

		defineTool("wiki_list", {
			description: "List all wiki pages",
			parameters: z.object({}),
			handler: async () => {
				const { listPages } = await import("../wiki/fs.js");
				return await listPages();
			},
		}),

		defineTool("wiki_search", {
