		// --- Shell Tool ---
		defineTool("shell_exec", {
			description:
				"Execute a shell command on the host machine. Use for git, gh CLI, file operations, etc. Commands run in the user's environment with their credentials.",
			parameters: z.object({
				command: z.string().describe("Shell command to execute"),
				cwd: z
					.string()
					.optional()
					.describe("Working directory (defaults to home directory)"),
			}),
			handler: async ({ command, cwd }) => {
				const { exec } = await import("node:child_process");
				const { promisify } = await import("node:util");
				const { homedir } = await import("node:os");
				const { buildShellEnv } = await import("./shell-env.js");
				const execAsync = promisify(exec);

				const shellEnv = buildShellEnv();

				try {
					const { stdout } = await execAsync(command, {
						cwd: cwd ?? homedir(),
						timeout: 60_000,
						maxBuffer: 1024 * 1024,
						env: shellEnv,
					});
					const output = stdout.trim() || "(no output)";
					addAuditEntry("shell_command", `Command: ${command.slice(0, 200)}`, {
						command,
						cwd,
						output: output.slice(0, 500),
						exit_code: 0,
					});
					return output;
				} catch (err: any) {
					const stderr = err.stderr?.toString().trim() ?? "";
					const stdout = err.stdout?.toString().trim() ?? "";
					const output = `Error (exit ${err.code}): ${stderr || stdout || err.message}`;
					addAuditEntry("shell_command", `Command: ${command.slice(0, 200)}`, {
						command,
						cwd,
						output: output.slice(0, 500),
						exit_code: err.code ?? 1,
					});
					return output;
				}
			},
		}),

		// --- Web Tools ---
		// NOTE: web_search and web_fetch are provided by the Copilot SDK as built-in tools.
		// Do not define them here to avoid conflicts.
	];
}

import { randomUUID } from "node:crypto";
import { getDb } from "./db.js";

export interface AuditEntry {
  id: string;
  squad_id: string | null;
  agent_id: string | null;
  task_id: string | null;
  action_type: string;
  summary: string;
  payload: string;
  created_at: string;
}

export interface AuditLogFilters {
  squad_id?: string;
  agent_id?: string;
  action_type?: string;
  from?: string;
  to?: string;
  limit?: number;
  offset?: number;
}

export function addAuditEntry(
  action_type: string,
  summary: string,
  payload: object,
  opts?: { squad_id?: string; agent_id?: string; task_id?: string }
): AuditEntry {
  const db = getDb();
  const id = randomUUID();
  db.prepare(
    `INSERT INTO audit_log (id, squad_id, agent_id, task_id, action_type, summary, payload)
     VALUES (?, ?, ?, ?, ?, ?, ?)`
  ).run(
    id,
    opts?.squad_id ?? null,
    opts?.agent_id ?? null,
    opts?.task_id ?? null,
    action_type,
    summary,
    JSON.stringify(payload)
  );
  return db.prepare("SELECT * FROM audit_log WHERE id = ?").get(id) as AuditEntry;
}

export function getAuditLog(filters: AuditLogFilters = {}): AuditEntry[] {
  const db = getDb();
  const conditions: string[] = [];
  const params: unknown[] = [];

  if (filters.squad_id) {
    conditions.push("squad_id = ?");
    params.push(filters.squad_id);
  }
  if (filters.agent_id) {
    conditions.push("agent_id = ?");
    params.push(filters.agent_id);
  }
  if (filters.action_type) {
    conditions.push("action_type = ?");
    params.push(filters.action_type);
  }
  if (filters.from) {
    conditions.push("created_at >= ?");
    params.push(filters.from);
  }
  if (filters.to) {
    conditions.push("created_at <= ?");
    params.push(filters.to);
  }

  const where = conditions.length > 0 ? `WHERE ${conditions.join(" AND ")}` : "";
  const limit = filters.limit ?? 50;
  const offset = filters.offset ?? 0;

  return db
    .prepare(`SELECT * FROM audit_log ${where} ORDER BY created_at DESC LIMIT ? OFFSET ?`)
    .all(...params, limit, offset) as AuditEntry[];
}

export function countAuditLog(filters: AuditLogFilters = {}): number {
  const db = getDb();
  const conditions: string[] = [];
  const params: unknown[] = [];

  if (filters.squad_id) {
    conditions.push("squad_id = ?");
    params.push(filters.squad_id);
  }
  if (filters.agent_id) {
    conditions.push("agent_id = ?");
    params.push(filters.agent_id);
  }
  if (filters.action_type) {
    conditions.push("action_type = ?");
    params.push(filters.action_type);
  }
  if (filters.from) {
    conditions.push("created_at >= ?");
    params.push(filters.from);
  }
  if (filters.to) {
    conditions.push("created_at <= ?");
    params.push(filters.to);
  }

  const where = conditions.length > 0 ? `WHERE ${conditions.join(" AND ")}` : "";
  const row = db
    .prepare(`SELECT COUNT(*) as count FROM audit_log ${where}`)
    .get(...params) as { count: number };
  return row.count;
}

import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join, basename, resolve, sep, dirname } from "node:path";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { fileURLToPath } from "node:url";
import YAML from "yaml";
import { PATHS } from "../paths.js";

const execFileAsync = promisify(execFile);

/** Path to bundled skills shipped with the daemon (repo/skills/) */
const BUNDLED_SKILLS = resolve(dirname(fileURLToPath(import.meta.url)), "../../skills");

export interface SkillInfo {
  name: string;
  slug: string;
  description: string;
  path: string;
}

export async function listSkills(): Promise<SkillInfo[]> {
  if (!existsSync(PATHS.skills)) return [];

  const entries = readdirSync(PATHS.skills, { withFileTypes: true });
  const skills: SkillInfo[] = [];

  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const skillMd = join(PATHS.skills, entry.name, "SKILL.md");
    if (!existsSync(skillMd)) continue;

    const content = readFileSync(skillMd, "utf-8");
    const { body } = parseSkillFrontmatter(content);

    const lines = body.replace(/\r\n/g, "\n").replace(/\r/g, "\n").split("\n");
    const firstLine = lines.find((l) => l.startsWith("# "));
    const name = firstLine?.replace(/^#\s+/, "") ?? entry.name;
    const description = extractSkillDescription(content);

    skills.push({
      name,
      slug: entry.name,
      description,
      path: join(PATHS.skills, entry.name),
    });
  }

  return skills;
}

export async function addSkill(url: string): Promise<void> {
  const slug = basename(url, ".git").replace(/[^a-z0-9-]/gi, "-").toLowerCase();
  const dest = join(PATHS.skills, slug);

  if (existsSync(dest)) {
    throw new Error(`Skill "${slug}" is already installed.`);
  }

  await execFileAsync("git", ["clone", "--depth", "1", "--", url, dest]);

  // Verify SKILL.md exists
  if (!existsSync(join(dest, "SKILL.md"))) {
    rmSync(dest, { recursive: true, force: true });
    throw new Error("Repository does not contain a SKILL.md file.");
  }
}

export async function removeSkill(slug: string): Promise<void> {
  const dest = join(PATHS.skills, slug);
  if (!existsSync(dest)) {
    throw new Error(`Skill "${slug}" not found.`);
  }
  rmSync(dest, { recursive: true, force: true });
}

export async function getSkillContent(slug: string): Promise<string> {
  const skillMd = join(PATHS.skills, slug, "SKILL.md");
  if (!existsSync(skillMd)) {
    throw new Error(`Skill "${slug}" not found.`);
  }
  return readFileSync(skillMd, "utf-8");
}

export async function updateSkillContent(slug: string, content: string): Promise<void> {
  const skillMd = join(PATHS.skills, slug, "SKILL.md");
  if (!existsSync(join(PATHS.skills, slug))) {
    throw new Error(`Skill "${slug}" not found.`);
  }
  writeFileSync(skillMd, content);
}

export async function createSkill(slug: string, content: string): Promise<void> {
  const cleanSlug = slug
    .trim()
    .replace(/[^a-z0-9-]/gi, "-")
    .toLowerCase()
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
  if (!cleanSlug) {
    throw new Error("Skill title must contain at least one alphanumeric character.");
  }

  // Guard against path traversal: the resolved destination must be a direct
  // child of the skills directory (not above or beside it).
  const skillsRoot = resolve(PATHS.skills);
  const dest = resolve(skillsRoot, cleanSlug);
  if (!dest.startsWith(skillsRoot + sep)) {
    throw new Error("Invalid skill slug.");
  }

  if (existsSync(dest)) {
    throw new Error(`Skill "${cleanSlug}" already exists.`);
  }
  mkdirSync(dest, { recursive: true });
  writeFileSync(join(dest, "SKILL.md"), content);
}

export async function loadSkillDirectories(): Promise<string[]> {
  const dirs: string[] = [];

  // User-installed skills (~/.io/skills/)
  if (existsSync(PATHS.skills)) {
    const entries = readdirSync(PATHS.skills, { withFileTypes: true });
    for (const e of entries) {
      if (e.isDirectory() && existsSync(join(PATHS.skills, e.name, "SKILL.md"))) {
        dirs.push(join(PATHS.skills, e.name));
      }
    }
  }

  // Bundled skills shipped with the daemon (repo/skills/)
  if (existsSync(BUNDLED_SKILLS)) {
    const entries = readdirSync(BUNDLED_SKILLS, { withFileTypes: true });
    for (const e of entries) {
      if (e.isDirectory() && existsSync(join(BUNDLED_SKILLS, e.name, "SKILL.md"))) {
        dirs.push(join(BUNDLED_SKILLS, e.name));
      }
    }
  }

  return dirs;
}

/**
 * Load squad-specific skill directories from the squad's wiki area.
 * Skills are stored at ~/.io/wiki/pages/squads/<squadSlug>/skills/<name>/SKILL.md
 */
export function loadSquadSkillDirectories(squadSlug: string): string[] {
  const squadSkillsDir = join(PATHS.wikiPages, "squads", squadSlug, "skills");
  if (!existsSync(squadSkillsDir)) return [];

  const entries = readdirSync(squadSkillsDir, { withFileTypes: true });
  return entries
    .filter((e) => e.isDirectory() && existsSync(join(squadSkillsDir, e.name, "SKILL.md")))
    .map((e) => join(squadSkillsDir, e.name));
}

// ---- Community skill discovery ----

export type DiscoverySource = "awesome-copilot" | "skillssh";

export const GITHUB_REPO_PATH = /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/;

export function isGitHubRepoPath(value: string): boolean {
  return GITHUB_REPO_PATH.test(value.trim());
}

interface DiscoveredSkill {
  slug: string;
  name: string;
  description: string;
  source: DiscoverySource;
  /** GitHub repo path (e.g., "clerk/skills") for skillssh sources */
  sourceRepo?: string;
  /** Install count from skills.sh */
  installs?: number;
}

interface DiscoveryCache {
  skills: DiscoveredSkill[];
  fetchedAt: number;
}

const DISCOVERY_CACHE = new Map<DiscoverySource, DiscoveryCache>();
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

/** Validate and return a safe slug, throwing if it contains unsafe characters. */
function validateSlug(slug: string): string {
  if (!slug || !/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i.test(slug)) {
    throw new Error("Invalid skill slug: must contain only letters, digits, and hyphens.");
  }
  return slug;
}

function parseSkillFrontmatter(content: string) {
  const trimmed = content.trimStart();
  if (!trimmed.startsWith("---")) {
    return { body: content, frontmatter: null };
  }

  const match = trimmed.match(/^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)([\s\S]*)$/);
  if (!match) {
    return { body: content, frontmatter: null };
  }

  const frontmatter = YAML.parseDocument(match[1], { prettyErrors: true });
  return {
    body: match[2],
    frontmatter: frontmatter.toJS() as Record<string, unknown> | null,
  };
}

function extractSkillDescription(content: string): string {
  const { body, frontmatter } = parseSkillFrontmatter(content);
  const frontmatterDescription =
    typeof frontmatter?.description === "string"
      ? frontmatter.description.trim()
      : "";
  if (frontmatterDescription) {
    return frontmatterDescription;
  }

  const lines = body.replace(/\r\n/g, "\n").replace(/\r/g, "\n").split("\n");
  return lines.find((line) => line.trim() && !line.startsWith("#"))?.trim() || "";
}

function parseAwesomeCopilotTable(markdown: string): DiscoveredSkill[] {
  const skills: DiscoveredSkill[] = [];
  for (const line of markdown.split("\n")) {
    if (!line.startsWith("|")) continue;
    const cells = line
      .split("|")
      .map((c) => c.trim())
      .filter(Boolean);
    if (cells.length < 2) continue;

    // First cell contains [slug](../skills/slug/SKILL.md)
    const slugMatch = cells[0].match(/^\[([^\]]+)\]/);
    if (!slugMatch) continue;
    const slug = slugMatch[1];
    if (slug === "Name") continue; // header row

    // Second cell is the description (may contain <br /> markup)
    const description = cells[1]
      .replace(/<br\s*\/?>/gi, " ")
      .replace(/\*\*([^*]+)\*\*/g, "$1")
      .trim();
    if (!description || description === "Description") continue;

    skills.push({ slug, name: slug, description, source: "awesome-copilot" });
  }
  return skills;
}

async function fetchAwesomeCopilotSkills(): Promise<DiscoveredSkill[]> {
  const url =
    "https://raw.githubusercontent.com/github/awesome-copilot/main/docs/README.skills.md";
  const res = await fetch(url, { signal: AbortSignal.timeout(15_000) });
  if (!res.ok) throw new Error(`Failed to fetch awesome-copilot skills list: HTTP ${res.status}`);
  const text = await res.text();
  return parseAwesomeCopilotTable(text);
}

interface SkillsShSearchResult {
  id: string;
  skillId: string;
  name: string;
  installs: number;
  source: string;
}

interface SkillsShSearchResponse {
  skills: SkillsShSearchResult[];
  count: number;
}

async function fetchRemoteSkillDescription(
  sourceRepo: string,
  skillId: string,
): Promise<string> {
  try {
    const safeSlug = validateSlug(skillId);
    const skillPath = await findSkillPathInRepo(sourceRepo, safeSlug);
    const rawUrl = `https://raw.githubusercontent.com/${sourceRepo}/main/${skillPath}`;
    const res = await fetch(rawUrl, { signal: AbortSignal.timeout(10_000) });
    if (!res.ok) return "";
    return extractSkillDescription(await res.text());
  } catch {
    return "";
  }
}

async function fetchSkillsShSkills(query?: string): Promise<DiscoveredSkill[]> {
  try {
    const searchQuery = query?.trim() || "";
    const url = `https://skills.sh/api/search?q=${encodeURIComponent(searchQuery)}`;
    const res = await fetch(url, {
      headers: { Accept: "application/json" },
      signal: AbortSignal.timeout(10_000),
    });
    if (!res.ok) return [];
    const data = (await res.json()) as SkillsShSearchResponse;
    const filtered = data.skills
      .map((item) => ({
        slug: item.skillId || item.name || "",
        name: item.name || item.skillId || "",
        description: "",
        source: "skillssh" as const,
        sourceRepo: item.source,
        installs: item.installs,
      }))
      .filter((item) => item.sourceRepo ? isGitHubRepoPath(item.sourceRepo) : false);

    return await Promise.all(
      filtered.map(async (item) => {
        const description = item.sourceRepo
          ? await fetchRemoteSkillDescription(item.sourceRepo, item.slug)
          : "";
        return { ...item, description };
      }),
    );
  } catch {
    return [];
  }
}

export async function discoverSkills(
  source: DiscoverySource,
  query?: string
): Promise<DiscoveredSkill[]> {
  // For skills.sh, use the search API directly with the query
  if (source === "skillssh") {
    return fetchSkillsShSkills(query);
  }

  // For awesome-copilot, use caching and client-side filtering
  const cached = DISCOVERY_CACHE.get(source);
  let skills: DiscoveredSkill[];

  if (cached && Date.now() - cached.fetchedAt < CACHE_TTL_MS) {
    skills = cached.skills;
  } else {
    skills = await fetchAwesomeCopilotSkills();
    DISCOVERY_CACHE.set(source, { skills, fetchedAt: Date.now() });
  }

  if (query) {
    const q = query.toLowerCase();
    skills = skills.filter(
      (s) => s.slug.toLowerCase().includes(q) || s.description.toLowerCase().includes(q)
    );
  }

  return skills;
}

/**
 * Find the path to SKILL.md in a GitHub repo by searching the repo tree.
 * Returns the full path (e.g., "skills/features/clerk-testing/SKILL.md").
 */
async function findSkillPathInRepo(
  repoPath: string,
  skillId: string
): Promise<string> {
  const treeUrl = `https://api.github.com/repos/${repoPath}/git/trees/main?recursive=1`;
  const res = await fetch(treeUrl, { signal: AbortSignal.timeout(10_000) });
  if (!res.ok) {
    throw new Error(`Failed to fetch repo tree for "${repoPath}": HTTP ${res.status}`);
  }

  interface TreeItem {
    path: string;
    type: string;
  }
  const data = (await res.json()) as { tree: TreeItem[] };

  // Look for a SKILL.md file in a folder named after the skillId
  const targetSuffix = `${skillId}/SKILL.md`;
  const match = data.tree.find(
    (item) => item.type === "blob" && item.path.endsWith(targetSuffix)
  );

  if (!match) {
    throw new Error(`Could not find SKILL.md for "${skillId}" in repo "${repoPath}"`);
  }

  return match.path;
}

function remoteSkillMdUrl(source: DiscoverySource, safeSlug: string): string {
  const encodedSlug = encodeURIComponent(safeSlug);
  if (source === "awesome-copilot") {
    return `https://raw.githubusercontent.com/github/awesome-copilot/main/skills/${encodedSlug}/SKILL.md`;
  }
  // Legacy fallback for skillssh without sourceRepo (shouldn't be used anymore)
  return `https://skills.sh/skills/${encodedSlug}/SKILL.md`;
}

export async function fetchRemoteSkillPreview(
  source: DiscoverySource,
  slug: string,
  sourceRepo?: string
): Promise<string> {
  const safeSlug = validateSlug(slug);

  // For skillssh with a sourceRepo, use GitHub directly
  if (source === "skillssh" && sourceRepo) {
    const skillPath = await findSkillPathInRepo(sourceRepo, safeSlug);
    const rawUrl = `https://raw.githubusercontent.com/${sourceRepo}/main/${skillPath}`;
    const res = await fetch(rawUrl, { signal: AbortSignal.timeout(10_000) });
    if (!res.ok) {
      throw new Error(`Failed to fetch preview for "${safeSlug}": HTTP ${res.status}`);
    }
    return res.text();
  }

  // Fallback to legacy URL approach
  const url = remoteSkillMdUrl(source, safeSlug);
  const res = await fetch(url, { signal: AbortSignal.timeout(10_000) });
  if (!res.ok) throw new Error(`Failed to fetch preview for "${safeSlug}": HTTP ${res.status}`);
  return res.text();
}

export async function installFromSource(
  source: DiscoverySource,
  slug: string,
  sourceRepo?: string
): Promise<void> {
  const safeSlug = validateSlug(slug);
  const dest = join(PATHS.skills, safeSlug);
  if (existsSync(dest)) {
    throw new Error(`Skill "${safeSlug}" is already installed.`);
  }
  const content = await fetchRemoteSkillPreview(source, safeSlug, sourceRepo);
  mkdirSync(dest, { recursive: true });
  writeFileSync(join(dest, "SKILL.md"), content);
}

import { loadMcpConfig, type McpServerConfig } from "./config.js";
import type { MCPServerConfig } from "@github/copilot-sdk";

// Module-level array of MCP tools loaded at startup
let loadedServers: McpServerConfig[] = [];

export function initMcpRegistry(): void {
  loadedServers = loadMcpConfig().filter((s) => s.enabled);
}

export function getMcpServersForSession(): Record<string, MCPServerConfig> | undefined {
  if (loadedServers.length === 0) return undefined;

  const result: Record<string, MCPServerConfig> = {};
  for (const server of loadedServers) {
    if (server.type === "stdio" && server.command) {
      result[server.name] = {
        type: "local",
        command: server.command,
        args: server.args ?? [],
        env: server.env,
        tools: ["*"],
      } as any;
    } else if (server.type === "http" && server.url) {
      result[server.name] = {
        type: "http",
        url: server.url,
        headers: server.headers,
      } as any;
    }
  }
  return Object.keys(result).length > 0 ? result : undefined;
}

export function listServers(): McpServerConfig[] {
  return loadMcpConfig();
}

export function addServerToRegistry(server: McpServerConfig): void {
  if (server.enabled) {
    loadedServers.push(server);
  }
}

export function removeServerFromRegistry(id: string): void {
  loadedServers = loadedServers.filter((s) => s.id !== id);
}

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { PATHS } from "../paths.js";

export interface McpServerConfig {
  id: string;
  name: string;
  type: "stdio" | "http";
  command?: string;
  args?: string[];
  env?: Record<string, string>;
  url?: string;
  headers?: Record<string, string>;
  enabled: boolean;
}

export function loadMcpConfig(): McpServerConfig[] {
  if (!existsSync(PATHS.mcpConfig)) return [];
  const raw = JSON.parse(readFileSync(PATHS.mcpConfig, "utf-8"));
  return Array.isArray(raw.servers) ? raw.servers : [];
}

export function saveMcpConfig(servers: McpServerConfig[]): void {
  writeFileSync(PATHS.mcpConfig, JSON.stringify({ servers }, null, 2) + "\n");
}

export function addMcpServer(server: McpServerConfig): void {
  const servers = loadMcpConfig();
  servers.push(server);
  saveMcpConfig(servers);
}

export function removeMcpServer(id: string): void {
  const servers = loadMcpConfig().filter((s) => s.id !== id);
  saveMcpConfig(servers);
}

export function toggleMcpServer(id: string, enabled: boolean): void {
  const servers = loadMcpConfig();
  const server = servers.find((s) => s.id === id);
  if (server) {
    server.enabled = enabled;
    saveMcpConfig(servers);
  }
}

import { CopilotClient } from "@github/copilot-sdk";
import { getGhToken } from "./gh-token.js";

let client: CopilotClient | undefined;

export function getCopilotClientOptions(): ConstructorParameters<typeof CopilotClient>[0] {
  const githubToken = getGhToken();
  return githubToken ? { gitHubToken: githubToken } : {};
}

export async function getClient(): Promise<CopilotClient> {
  if (!client) {
    client = new CopilotClient(getCopilotClientOptions());
    await client.start();
  }
  return client;
}

export async function resetClient(): Promise<CopilotClient> {
  if (client) {
    try {
      await client.stop();
    } catch {
      // ignore stop errors during reset
    }
    client = undefined;
  }
  return getClient();
}

export function getClientInstance(): CopilotClient | undefined {
  return client;
}

import { execSync } from "node:child_process";
import { loadConfig, resetConfigCache } from "../config.js";

/**
 * Cached GitHub token for CLI operations.
 * Resolution order: GH_TOKEN env → GITHUB_TOKEN env → config.githubToken → `gh auth token` CLI.
 * If no token found, retries on next call (config may have been updated).
 */
let cachedToken: string | undefined;
let resolved = false;

export function resetGhTokenCache(): void {
  cachedToken = undefined;
  resolved = false;
}

export function getGhToken(): string | undefined {
  if (resolved && cachedToken) return cachedToken;

  // 1. Prefer explicit env vars
  if (process.env.GH_TOKEN) {
    cachedToken = process.env.GH_TOKEN;
    resolved = true;
    return cachedToken;
  }
  if (process.env.GITHUB_TOKEN) {
    cachedToken = process.env.GITHUB_TOKEN;
    resolved = true;
    return cachedToken;
  }

  // 2. Check IO config file (re-read in case it was updated since last attempt)
  try {
    if (!cachedToken) resetConfigCache();
    const config = loadConfig();
    if (config.githubToken) {
      cachedToken = config.githubToken;
      resolved = true;
      return cachedToken;
    }
  } catch {
    // Config not available
  }

  // 3. Try extracting from gh CLI auth (only on first attempt)
  if (!resolved) {
    try {
      const token = execSync("gh auth token", {
        timeout: 5_000,
        encoding: "utf-8",
        stdio: ["pipe", "pipe", "pipe"],
      }).trim();
      if (token) {
        cachedToken = token;
        resolved = true;
      }
    } catch {
      // gh not available or not authenticated
    }
  }

  // Mark resolved only if we found a token — otherwise retry next call
  if (cachedToken) resolved = true;
  return cachedToken;
}

import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { randomUUID } from "node:crypto";
import { PATHS } from "../paths.js";

export interface MessageAttachment {
  name: string;
  mimeType: string;
  size: number;
  content: string;
}

export interface SavedAttachment {
  name: string;
  mimeType: string;
  size: number;
  path: string;
}

export const MAX_ATTACHMENT_BYTES = 10 * 1024 * 1024;
export const MAX_TOTAL_ATTACHMENT_BYTES = 25 * 1024 * 1024;

const BASE64_RE = /^[A-Za-z0-9+/]*={0,2}$/;

function isValidBase64(value: string): boolean {
  if (!value || value.length % 4 !== 0) return false;
  return BASE64_RE.test(value);
}

function isMessageAttachment(value: unknown): value is MessageAttachment {
  if (!value || typeof value !== "object") return false;
  const candidate = value as Partial<MessageAttachment>;
  return (
    typeof candidate.name === "string" &&
    candidate.name.trim().length > 0 &&
    typeof candidate.mimeType === "string" &&
    candidate.mimeType.trim().length > 0 &&
    typeof candidate.size === "number" &&
    Number.isFinite(candidate.size) &&
    candidate.size >= 0 &&
    typeof candidate.content === "string"
  );
}

export function validateMessageAttachments(
  input: unknown
): { ok: true; attachments: MessageAttachment[] } | { ok: false; error: string } {
  if (input === undefined || input === null) {
    return { ok: true, attachments: [] };
  }
  if (!Array.isArray(input)) {
    return { ok: false, error: "attachments must be an array" };
  }

  let totalSize = 0;
  const attachments: MessageAttachment[] = [];
  for (const raw of input) {
    if (!isMessageAttachment(raw)) {
      return {
        ok: false,
        error: "each attachment must include name, mimeType, size, and content",
      };
    }

    if (raw.size > MAX_ATTACHMENT_BYTES) {
      return { ok: false, error: "each attachment must be 10MB or smaller" };
    }

    if (!isValidBase64(raw.content)) {
      return { ok: false, error: `attachment "${raw.name}" has invalid base64 content` };
    }

    const trimmedName = raw.name.trim();
    const trimmedMimeType = raw.mimeType.trim();
    if (!trimmedName || !trimmedMimeType) {
      return { ok: false, error: "attachment name and mimeType are required" };
    }

    totalSize += raw.size;
    attachments.push({
      name: trimmedName,
      mimeType: trimmedMimeType,
      size: raw.size,
      content: raw.content,
    });
  }

  if (totalSize > MAX_TOTAL_ATTACHMENT_BYTES) {
    return { ok: false, error: "total attachment size must be 25MB or smaller" };
  }

  return { ok: true, attachments };
}

export function toCopilotBlobAttachments(
  attachments: MessageAttachment[]
): Array<{ type: "blob"; data: string; mimeType: string; displayName?: string }> {
  return attachments.map((attachment) => ({
    type: "blob",
    data: attachment.content,
    mimeType: attachment.mimeType,
    displayName: attachment.name,
  }));
}

export function buildAttachmentSummary(attachments: MessageAttachment[]): string {
  if (attachments.length === 0) return "";
  const lines = attachments.map(
    (attachment) =>
      `- ${attachment.name} (${attachment.mimeType}, ${Math.round(attachment.size / 1024)}KB)`
  );
  return `\n\n[Attachments]\n${lines.join("\n")}`;
}

/**
 * Save attachments to disk at ~/.io/attachments/{batchId}/{filename}
 * Returns the saved paths so they can be referenced by the orchestrator and squads.
 */
export function saveAttachmentsToDisk(attachments: MessageAttachment[]): SavedAttachment[] {
  if (attachments.length === 0) return [];

  const batchId = randomUUID();
  const batchDir = join(PATHS.attachments, batchId);
  if (!existsSync(PATHS.attachments)) mkdirSync(PATHS.attachments, { recursive: true });
  mkdirSync(batchDir, { recursive: true });

  return attachments.map((attachment) => {
    const filePath = join(batchDir, attachment.name);
    writeFileSync(filePath, Buffer.from(attachment.content, "base64"));
    return {
      name: attachment.name,
      mimeType: attachment.mimeType,
      size: attachment.size,
      path: filePath,
    };
  });
}

/**
 * Build a summary that includes file paths on disk for tool access.
 */
export function buildAttachmentPathSummary(saved: SavedAttachment[]): string {
  if (saved.length === 0) return "";
  const lines = saved.map(
    (s) => `- ${s.name} (${s.mimeType}, ${Math.round(s.size / 1024)}KB) → ${s.path}`
  );
  return `\n\n[Attached files saved to disk]\n${lines.join("\n")}`;
}

import type { CopilotSession } from "@github/copilot-sdk";
import { loadConfig } from "../config.js";
import { recordTokenUsage } from "../store/token-usage.js";
import { postFeedItem } from "../store/feed.js";

interface UsageAccumulator {
  [model: string]: { inputTokens: number; outputTokens: number };
}

/**
 * Attach a token usage listener to a CopilotSession.
 * Returns a `flush` function that, when called, persists accumulated
 * token usage to the database and returns the totals.
 *
 * Call `flush` after the session ends (in a finally block).
 */
export function attachTokenTracker(
  session: CopilotSession,
  context: {
    squadId?: string;
    agentId?: string;
    taskId?: string;
  }
): () => { totalInputTokens: number; totalOutputTokens: number } {
  const accumulator: UsageAccumulator = {};

  const unsubscribe = session.on("assistant.usage" as any, (event: any) => {
    const data = event?.data;
    if (!data?.model) return;
    const model: string = data.model;
    const input: number = data.inputTokens ?? 0;
    const output: number = data.outputTokens ?? 0;
    if (!accumulator[model]) accumulator[model] = { inputTokens: 0, outputTokens: 0 };
    accumulator[model].inputTokens += input;
    accumulator[model].outputTokens += output;
  });

  return () => {
    unsubscribe();

    let totalInputTokens = 0;
    let totalOutputTokens = 0;

    for (const [model, usage] of Object.entries(accumulator)) {
      if (usage.inputTokens === 0 && usage.outputTokens === 0) continue;
      recordTokenUsage({
        squadId: context.squadId,
        agentId: context.agentId,
        taskId: context.taskId,
        model,
        inputTokens: usage.inputTokens,
        outputTokens: usage.outputTokens,
      });
      totalInputTokens += usage.inputTokens;
      totalOutputTokens += usage.outputTokens;
    }

    // Alert on runaway agents
    const config = loadConfig();
    const threshold = config.tokenAlertThreshold;
    if (threshold && (totalInputTokens + totalOutputTokens) > threshold) {
      const source = context.squadId ? `squad-${context.squadId}` : "system";
      postFeedItem(
        source,
        "⚠️ Token usage alert",
        `A task consumed ${totalInputTokens + totalOutputTokens} tokens (threshold: ${threshold}). ` +
          (context.taskId ? `Task ID: ${context.taskId}` : "")
      );
    }

    return { totalInputTokens, totalOutputTokens };
  };
}

import { randomUUID } from "node:crypto";
import { getDb } from "./db.js";

export interface TokenUsageRecord {
  id: string;
  squad_id: string | null;
  agent_id: string | null;
  task_id: string | null;
  model: string;
  input_tokens: number;
  output_tokens: number;
  created_at: string;
}

export interface TokenUsageSummary {
  total_records: number;
  total_input_tokens: number;
  total_output_tokens: number;
  total_tokens: number;
}

export interface TokenUsageByGroup {
  id: string;
  name: string;
  total_input_tokens: number;
  total_output_tokens: number;
  total_tokens: number;
  record_count: number;
}

export interface DailyTokenUsage {
  date: string;
  total_input_tokens: number;
  total_output_tokens: number;
  total_tokens: number;
}

export function recordTokenUsage(params: {
  squadId?: string;
  agentId?: string;
  taskId?: string;
  model: string;
  inputTokens: number;
  outputTokens: number;
}): TokenUsageRecord {
  const db = getDb();
  const id = randomUUID();
  db.prepare(
    `INSERT INTO token_usage (id, squad_id, agent_id, task_id, model, input_tokens, output_tokens)
     VALUES (?, ?, ?, ?, ?, ?, ?)`
  ).run(
    id,
    params.squadId ?? null,
    params.agentId ?? null,
    params.taskId ?? null,
    params.model,
    params.inputTokens,
    params.outputTokens
  );
  return db.prepare("SELECT * FROM token_usage WHERE id = ?").get(id) as TokenUsageRecord;
}

export function getTokenUsageSummary(opts?: { since?: string }): TokenUsageSummary {
  const db = getDb();
  let sql = `SELECT
    COUNT(*) as total_records,
    COALESCE(SUM(input_tokens), 0) as total_input_tokens,
    COALESCE(SUM(output_tokens), 0) as total_output_tokens,
    COALESCE(SUM(input_tokens + output_tokens), 0) as total_tokens
  FROM token_usage WHERE 1=1`;
  const params: string[] = [];
  if (opts?.since) {
    sql += " AND created_at >= ?";
    params.push(opts.since);
  }
  return db.prepare(sql).get(...params) as TokenUsageSummary;
}

export function getTokenUsageBySquad(opts?: { since?: string }): TokenUsageByGroup[] {
  const db = getDb();
  let sql = `SELECT
    s.id,
    s.name,
    COALESCE(SUM(t.input_tokens), 0) as total_input_tokens,
    COALESCE(SUM(t.output_tokens), 0) as total_output_tokens,
    COALESCE(SUM(t.input_tokens + t.output_tokens), 0) as total_tokens,
    COUNT(t.id) as record_count
  FROM squads s
  LEFT JOIN token_usage t ON t.squad_id = s.id`;
  const params: string[] = [];
  if (opts?.since) {
    sql += " AND t.created_at >= ?";
    params.push(opts.since);
  }
  sql += " GROUP BY s.id ORDER BY total_tokens DESC";
  return db.prepare(sql).all(...params) as TokenUsageByGroup[];
}

export function getTokenUsageByAgent(opts?: { squadId?: string; since?: string }): TokenUsageByGroup[] {
  const db = getDb();
  let sql = `SELECT
    a.id,
    a.character_name as name,
    COALESCE(SUM(t.input_tokens), 0) as total_input_tokens,
    COALESCE(SUM(t.output_tokens), 0) as total_output_tokens,
    COALESCE(SUM(t.input_tokens + t.output_tokens), 0) as total_tokens,
    COUNT(t.id) as record_count
  FROM agents a
  LEFT JOIN token_usage t ON t.agent_id = a.id`;
  const params: string[] = [];
  const conditions: string[] = [];
  if (opts?.squadId) {
    conditions.push("a.squad_id = ?");
    params.push(opts.squadId);
  }
  if (opts?.since) {
    conditions.push("(t.created_at >= ? OR t.created_at IS NULL)");
    params.push(opts.since);
  }
  if (conditions.length > 0) {
    sql += " WHERE " + conditions.join(" AND ");
  }
  sql += " GROUP BY a.id ORDER BY total_tokens DESC";
  return db.prepare(sql).all(...params) as TokenUsageByGroup[];
}

export function getDailyTokenUsage(days = 30): DailyTokenUsage[] {
  const db = getDb();
  const sql = `SELECT
    date(created_at) as date,
    COALESCE(SUM(input_tokens), 0) as total_input_tokens,
    COALESCE(SUM(output_tokens), 0) as total_output_tokens,
    COALESCE(SUM(input_tokens + output_tokens), 0) as total_tokens
  FROM token_usage
  WHERE created_at >= date('now', '-' || ? || ' days')
  GROUP BY date(created_at)
  ORDER BY date ASC`;
  return db.prepare(sql).all(days) as DailyTokenUsage[];
}

export function getTokenUsageForTask(taskId: string): TokenUsageRecord[] {
  const db = getDb();
  return db
    .prepare("SELECT * FROM token_usage WHERE task_id = ? ORDER BY created_at ASC")
    .all(taskId) as TokenUsageRecord[];
}

import { randomUUID } from "node:crypto";
import { getDb } from "./db.js";

export interface FeedItem {
  id: string;
  source: string;
  title: string;
  content: string;
  read: number;
  created_at: string;
}

export function postFeedItem(source: string, title: string, content: string): FeedItem {
  const db = getDb();
  const id = randomUUID();
  db.prepare(
    "INSERT INTO feed_items (id, source, title, content) VALUES (?, ?, ?, ?)"
  ).run(id, source, title, content);
  return db.prepare("SELECT * FROM feed_items WHERE id = ?").get(id) as FeedItem;
}

export function getFeedItems(opts?: {
  unreadOnly?: boolean;
  source?: string;
  limit?: number;
  offset?: number;
}): FeedItem[] {
  const db = getDb();
  let sql = "SELECT * FROM feed_items WHERE 1=1";
  const params: any[] = [];

  if (opts?.unreadOnly) {
    sql += " AND read = 0";
  }
  if (opts?.source) {
    sql += " AND source = ?";
    params.push(opts.source);
  }

  sql += " ORDER BY created_at DESC";

  if (opts?.limit) {
    sql += " LIMIT ?";
    params.push(opts.limit);
  }
  if (opts?.offset) {
    sql += " OFFSET ?";
    params.push(opts.offset);
  }

  return db.prepare(sql).all(...params) as FeedItem[];
}

export function markFeedItemRead(id: string): void {
  const db = getDb();
  db.prepare("UPDATE feed_items SET read = 1 WHERE id = ?").run(id);
}

export function deleteFeedItem(id: string): void {
  const db = getDb();
  db.prepare("DELETE FROM feed_items WHERE id = ?").run(id);
}

export function getUnreadCount(): number {
  const db = getDb();
  const row = db.prepare("SELECT COUNT(*) as count FROM feed_items WHERE read = 0").get() as {
    count: number;
  };
  return row.count;
}
